package org.codex.nfsugpreview;
import java.nio.*;
public class DrawBoundsTest {public static void main(String[] args){long checks=0;int[][] targets={{240,160},{3240,2160},{3840,2160},{239,161},{1,1}};
 for(int[] target:targets){int width=target[0],height=target[1];for(int l=0;l<=240;l+=7)for(int span:new int[]{0,1,37,240}){int r=Math.min(240,l+span);int[] clip=new NativeDrawBounds(l,r,0,160).scissor(width,height);for(int x=0;x<width;x++){boolean expected=(2L*x+1)*240>=2L*l*width&&(2L*x+1)*240<2L*r*width,actual=x>=clip[0]&&x<clip[0]+clip[2];if(expected!=actual)throw new AssertionError("Horizontal clip");checks++;}}
 for(int top=0;top<=160;top+=7)for(int span:new int[]{0,1,31,160}){int bottom=Math.min(160,top+span);int[] clip=new NativeDrawBounds(0,240,top,bottom).scissor(width,height);for(int y=0;y<height;y++){boolean expected=(2L*height-2L*y-1)*160>=2L*top*height&&(2L*height-2L*y-1)*160<2L*bottom*height,actual=y>=clip[1]&&y<clip[1]+clip[3];if(expected!=actual)throw new AssertionError("Vertical clip");checks++;}}}
 ByteBuffer old=ByteBuffer.allocate(24).order(ByteOrder.LITTLE_ENDIAN);old.putInt(0,0x3142464e);old.putShort(16,(short)10);old.putShort(18,(short)20);old.putShort(20,(short)30);old.putShort(22,(short)40);if(NativeDrawBounds.command(old,1,true,0).right!=240||NativeDrawBounds.command(old,1,false,0).left!=10)throw new AssertionError("World-only bounds");
 ByteBuffer newer=ByteBuffer.allocate(32).order(ByteOrder.LITTLE_ENDIAN);newer.putInt(0,0x3242464e);newer.putShort(24,(short)1);newer.putShort(26,(short)2);newer.putShort(28,(short)3);newer.putShort(30,(short)4);if(NativeDrawBounds.command(newer,1,true,0).left!=1)throw new AssertionError("Model bounds");
 System.out.println("PASS_DRAW_BOUNDS pixel_center_checks="+checks+" viewports=5 world_only_and_model_bounds=true");}}
